    RAPIER.RigidBodyDesc.dynamic()
      .setTranslation(x, y)
      .setLinvel(boatVx * M.dropSpeedMul, boatVy * M.dropSpeedMul)
      .setLinearDamping(M.linearDamping)
      .setAngularDamping(M.angularDamping)
